package com.collabspace.controller; import com.collabspace.dto.AuthDtos.*; import com.collabspace.service.*; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/auth") @RequiredArgsConstructor public class AuthController {private final AuthService auth; private final CurrentUserService current; @PostMapping("/register") public AuthResponse register(@Valid @RequestBody RegisterRequest r){return auth.register(r);} @PostMapping("/login") public AuthResponse login(@Valid @RequestBody LoginRequest r){return auth.login(r);} @PostMapping("/logout") public void logout(){} @GetMapping("/me") public UserResponse me(){return auth.toDto(current.get());}}